CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), full_name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK (role IN ('customer','rider','shop','admin')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS shops (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID REFERENCES users(id), name TEXT NOT NULL, phone TEXT, address TEXT, approved BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), shop_id UUID REFERENCES shops(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL CHECK (category IN ('groceries','food','parcels','shop_products')), description TEXT, price_kes INTEGER NOT NULL CHECK (price_kes >= 0), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_number BIGSERIAL UNIQUE, customer_id UUID NOT NULL REFERENCES users(id), shop_id UUID REFERENCES shops(id), rider_id UUID REFERENCES users(id), delivery_address TEXT NOT NULL, customer_phone TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','shopping','picked_up','on_the_way','delivered','cancelled')), subtotal_kes INTEGER NOT NULL CHECK (subtotal_kes >= 0), delivery_fee_kes INTEGER NOT NULL CHECK (delivery_fee_kes >= 0), service_fee_kes INTEGER NOT NULL CHECK (service_fee_kes >= 0), total_kes INTEGER NOT NULL CHECK (total_kes = subtotal_kes + delivery_fee_kes + service_fee_kes), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id UUID REFERENCES products(id), item_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price_kes INTEGER NOT NULL CHECK (unit_price_kes >= 0));
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id), provider TEXT NOT NULL CHECK (provider IN ('mpesa','cash')), amount_kes INTEGER NOT NULL CHECK (amount_kes >= 0), phone TEXT, merchant_request_id TEXT, checkout_request_id TEXT UNIQUE, mpesa_receipt_number TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','paid','failed','cancelled')), result_code TEXT, result_description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rider_locations (id BIGSERIAL PRIMARY KEY, rider_id UUID NOT NULL REFERENCES users(id), order_id UUID REFERENCES orders(id), latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_rider ON orders(rider_id, status);
CREATE INDEX IF NOT EXISTS idx_products_shop ON products(shop_id, active);
CREATE INDEX IF NOT EXISTS idx_locations_order ON rider_locations(order_id, recorded_at DESC);
